  'partner1.refusal.keysSelfService': 'لا تُنشأ المفاتيح ولا يُعاد تحديد نطاقها ولا تُستبدل من وحدة التحكم هذه؛ وإبطال أحد مفاتيحك هو التغيير الوحيد الذي يُجرى هنا.',
  'partner1.refusal.keysOverlap': 'لا يُقدَّم أي تداخل عند استبدال المفتاح: يتوقف المفتاح المُبطَل عن العمل فورًا.',
  'partner1.refusal.keysUsage': 'لا تُعرض أعداد الاستدعاءات أو معدلات الأخطاء أو أعداد التقييد: لا تحتفظ بها المنصة لكل مفتاح بعد.',
  'partner1.refusal.keysWriteScopes': 'لا يستطيع أي مفتاح البتّ في طلب أو تحريك أموال: كل نطاق يمكن أن يحمله المفتاح هو للقراءة.',
