  'partner1.refusal.testWorld': 'لا توجد بيئة اختبار منفصلة: المفتاح المعلَّم كمفتاح اختبار مُسمّى كذلك فقط.',
  'partner1.refusal.hooksNotHash': 'سرّ التوقيع ليس تجزئة ولا يُعرض أبدًا: تحتفظ به المنصة مشفّرًا، لأن المُرسِل يجب أن يعيد إنتاج كل توقيع.',
  'partner1.refusal.hooksAppEvents': 'لا يُرسَل أي حدث طلب أو موافقة إلى نقطة نهاية الشريك؛ الأحداث هي أحداث سجل قروضك ووثائقك الخاص.',
  'partner1.refusal.hooksSelfServe': 'لا تُضاف نقاط النهاية ولا تُفعَّل ولا تُمنح سرًّا جديدًا من وحدة التحكم هذه.',
  'partner1.refusal.hooksReplay': 'لا يُعاد إرسال أي تسليم من وحدة التحكم هذه؛ تعيد عمليات الشركاء في المنصة إرساله عند الطلب.',
