  'partner1.refusal.hooksAdminOnly': 'نقاط النهاية ليست مخفية عن الأدوار الأخرى: يقرؤها كل عضو في مؤسستك، ولا يرى أي عضو سرًّا أبدًا.',
  'partner1.refusal.statusApplication': 'لا يوجد طلب إعداد أولي أو رقم مرجعي؛ تُعدّ عمليات الشركاء في المنصة الشريكَ بموجب اتفاقية.',
