  'partner2.premiums.statement': 'تحصّل المنصة الأقساط التي يدفعها المزارعون عن الوثائق على منتجاتك، وتحتفظ بها في حساب الضمان التابع للمنصة. لم يُسوَّ شيء لمؤسستك بعد: يجري تحديد كيفية تحويل الأقساط إلى شركات التأمين وموعده مع مستشاري المنصة. العمولة والدعم الحكومي مسجَّلان على كل منتج؛ ولا يُحتسب أو يُطالَب بشيء عليهما اليوم.',
