  'partner2.refusal.preVerified': 'لا تصل أي دفعة مقترحات وقد تم التحقق منها مسبقًا: لا يُتحقَّق من أي شيء عن المزارع أو الحقل أو الحيوان أو الحساب عند التسجيل.',
  'partner2.refusal.issueAct': 'لا يُصدَر شيء من وحدة التحكم هذه ولا يوافق شخص ثانٍ على أي إصدار: تبدأ التغطية عند تأكيد دفعة المزارع.',
  'partner2.refusal.issueIdempotent': 'لا يُصدَر شيء هنا، فلا يوجد إصدار يُكرَّر أو يُحمى من التكرار.',
  'partner2.refusal.rejectRate': 'لا تستطيع شركة التأمين رفض مقترح على المنصة، فلا يوجد معدل للمقترحات المرفوضة.',
  'partner2.refusal.proposalLatency': 'لا يُعرض الوقت من المقترح إلى الوثيقة: أنت لا تتخذ أي خطوة في الطريق إلى التغطية، فالرقم سيقيس توقيت دفعة المزارع، لا عملك.',
  'partner2.refusal.holderDocument': 'لا يُرسَل مستند وثيقة ولا ملخص صوتي إلى أحد، ولا يُحتفظ بعدد المواسم على الوثيقة.',
  'partner2.refusal.parkedRows': 'لا يُعلَّق أي مقترح، ولا يُبلَّغ أي مزارع بشيء من وحدة التحكم هذه، ولا تُخصَّص شبكة محطات طقس لأي مقترح.',
  'partner2.refusal.clockPause': 'لا تعمل ساعة استجابة على المقترح، فلا يتوقف شيء عند فشل القراءة.',
  'partner2.refusal.unissuedGuarantee': 'نصف ذلك فقط صحيح: لا تصبح أي وثيقة سارية دون دفع، لكن دفعة المزارع تبدأ التغطية دون أي إجراء من شركة التأمين.',
  'partner2.refusal.partnerRoles': 'لا يوجد دور اكتتاب أو مالية أو امتثال: أدوار الشريك الأربعة تقرأ الحقائق نفسها.',
  'partner2.refusal.collectedSum': 'لا يُعرض مجموع الأقساط: لم يُحوَّل إليك شيء، فالإجمالي سيصف أموالًا لا تحتفظ بها.',
  'partner2.refusal.settlesNextDay': 'لا يُحدَّد موعد لوصول الأموال إلى مؤسستك: لم يُحسم بعد كيف ومتى تُحوَّل الأقساط.',
  'partner2.refusal.subsidyOwed': 'لا تُحتسب أي حصة حكومية على أنها مستحقة لك، ولا تُقيَّد في دفتر، ولا يُطالَب بها من أي بوابة.',
  'partner2.refusal.refundsLine': 'لا يُحسب أي استرداد ولا يُدفع عند إلغاء الوثيقة.',
  'partner2.refusal.remitBatches': 'لا توجد دفعة مدفوعات إليك، فلا يُدرج شيء ولا يُطابَق.',
  'partner2.refusal.rupeePolicyNo': 'لا يُطابَق أي قسط برقم وثيقة: لا تحمل أي وثيقة رقمًا من شركة تأمين اليوم.',
  'partner2.refusal.unpaidZero': 'لا يُصدَر شيء هنا: تصبح الوثيقة سارية فقط عند تأكيد دفعة المزارع.',
  'partner2.refusal.oneTransaction': 'الدفع والتغطية ليسا خطوة واحدة: يُسجَّل الدفع أولًا ثم تتبعه التغطية.',
  'partner2.refusal.railsUnaffected': 'لا يوجد مسار دفع إليك، لذا لا يمكن القول إن أيًّا منها لم يتأثر.',
  'partner2.refusal.premiumsFile': 'لا يُنشأ ملف أقساط: فهو سينشر أرقامًا عن أموال لم تتسلّمها.',
  'partner2.refusal.ruralQuota': 'لا تُقاس أي حصة تنظيمية على المنصة ولا يُشهد لها.',
  'partner2.refusal.claimsTime': 'لا يُبلَّغ هنا عن مدة المطالبات، ولا يُقال إن أي موعد تنظيمي قد استوفي.',
  'partner2.refusal.complaints': 'لا تُحصى أي شكوى ولا يُبلَّغ عن أي تصعيد على المنصة.',
  'partner2.refusal.extractsTable': 'لا يُدرج أي مستخرج أو إيصال أو بصمة ملف: لم يُنشأ أي منها لشريك.',
  'partner2.refusal.replay': 'لا يُحتفظ بأي عملية حساب ليعيد أحد تشغيلها: لم يُقيَّم شيء قط.',
  'partner2.refusal.schedule': 'لا يُنشأ أي مستخرج وفق أي جدول.',
  'partner2.refusal.downloadMark': 'لا يوجد أي تنزيل، لذا لا يُعلَّم شيء لكل تنزيل.',
  'partner2.refusal.priorPacks': 'لم تُنشأ أي حزمة تقارير قط، لذا لا يبقى منها شيء ولا ينتهي.',
  'partner2.refusal.drillIns': 'لا يوجد هنا عرض لتوقيت المطالبات أو لسجل المحفّزات: المطالبات تأتي في موجة لاحقة ولا يوجد سجل محفّزات.',
  'partner2.refusal.seasonArmed': 'لا يُفعَّل أي منتج مؤشري لموسم، ولا تُراقَب أي نافذة.',
  'partner2.refusal.indexFeed': 'لا يُستلم أي مؤشر طقس ولا يُفحص ولا يُعرض على أحد.',
  'partner2.refusal.runFigures': 'لا يُحسب عدد وثائق أو مجموع تعويضات أو مساحة لأي محفّز.',
  'partner2.refusal.setAside': 'لا تُجنَّب أي أموال لتعويض على المنصة.',
  'partner2.refusal.noHuman': 'لا يُصرف أي تعويض أبدًا دون أن يقرره شخص، ولا توجد صلاحية دائمة للإفراج عن الأموال.',
