  'partner2.refusal.loanKindsCount': 'لا يُدّعى أي عدد لأنواع القروض: يُطبع نوع كل منتج من سجل المنصة، أو على أنه غير مسجّل.',
  'partner2.refusal.termsCompared': 'لا يُعرض على المزارعين أي عرض لشروطك بجانب شروط المُقرضين الآخرين يمكن لهذه الوحدة أن تشهد له.',
  'partner2.refusal.eligibilityEvaluated': 'تُطبع قواعد الأهلية الخاصة بك كما هي مخزنة؛ لا شيء هنا يقيّمها، ولا يُدّعى شيء حول أي المزارعين يرون أي منتج.',
  'partner2.refusal.listedSameDay': 'لا يُدرج أي منتج من هذه الوحدة، ولا يُقطع أي وعد حول موعد رؤية المزارعين لمنتج.',
  'partner2.refusal.newApplicationsOnly': 'لا يسري أي تغيير في السعر من هذه الوحدة، ولا يُدّعى هنا أي قاعدة حول الطلبات التي قد يشملها التغيير.',
  'partner2.refusal.farmerDisplay': 'لا يُنشأ اليوم على المنصة أي نص موجّه للمزارعين من شروطك.',
  'partner2.refusal.membersQualify': 'لا يُعرض أي تقدير لعدد أعضاء منظمة قد يكونون مؤهلين: المُقرض لا يرى أبدًا أعداد أعضاء المنظمة.',
  'partner2.refusal.feeCharged': 'لا تُفرض رسوم إنشاء على أحد اليوم: الرسوم المسجلة على منتج هي بيانات، ومسار الرسوم في المنصة غير مفعّل.',
  'partner2.refusal.loanChangesRecorded': 'لا يُجرى أي تغيير على منتج ولا يُسجَّل من هذه الوحدة، ولم يُتحقق بعد مما إذا كان الطلب المقدَّم يحتفظ بالشروط التي قُدّم بموجبها.',
  'partner2.refusal.rateLimit': 'لا تفرض المنصة اليوم حدًا أقصى للسعر لكل نوع، ولا يُحفظ شيء من هذه الصفحة.',
