  'partner3.surveyors.title': 'المعاينون',
  'partner3.surveyors.statement': 'لا توجد قائمة معاينين على المنصة، وهذه الوحدة لا تدير موظفي أحد. تُرتّب المعاينات المنظمة التي تخدم المزارع.',
  'partner3.surveyors.lead': 'لا يوجد ما يُحصى في هذه الصفحة: لا يُحتفظ بالمعاين كسجل على المنصة، لذا لا توجد قائمة أو توافر أو تغطية أو عبء عمل أو مؤهلات لعرضها عليك.',
