  'partner3.fraud.statement': 'لا توجد علامات احتيال على المنصة، ولا تُرفع أي منها من هذه الوحدة.',
  'partner3.fraud.lead': 'لا يوجد ما يُحصى ولا ما يُدرج في هذه الصفحة: لا تحتفظ المنصة بأي علامة أو إشارة أو درجة عن أي مطالبة، وهذه الوحدة لا تعلّم أي مطالبة كمشبوهة أبدًا.',
  'partner3.chain.act3b.title': 'غير متاح من هذه الوحدة',
  'partner3.chain.act3b.confirm': 'هذا الإجراء غير متاح من وحدة الشركاء: تتولى المنظمة التي تخدم المزارع الأدلة والمعاينات والمعاينين، ولا توجد علامة احتيال على المنصة. لم يتغير شيء.',
  'partner3.refusal.claimPlaces': 'لا تُعرض قرية المطالبة أو مسارها أو قطعتها: ترى شركة التأمين وقائع المطالبة فقط، ولا ترى أبدًا أين يعيش المزارع أو يزرع.',
  'partner3.refusal.evidenceArrival': 'لا تصل إلى هنا أي مطالبة من مكالمة مع مزارع، ولا يوجد فحص آلي يُعاد تشغيله عند إعادة قراءة الصفحة.',
  'partner3.refusal.boardIdentity': 'لا يُذكر اسم أي مُطالِب، ولا يُعرض رقم هاتف، ولا يُعرض سجل حيوان أو ملف صحي: وقائع المطالبة هي الصفحة كلها.',
  'partner3.refusal.surveyBooking': 'لا تُحجز أي معاينة ولا تُؤكَّد ولا تُنقل ولا تُنفَّذ خارج الاتصال من هذه الوحدة، ولا شيء يحجز نفسه: المنظمة التي تخدم المزارع ترتّب كل معاينة.',
  'partner3.refusal.reportHolders': 'لا يُذكر اسم أي حامل وثيقة ولا تُعرض مساحة أي قطعة: لا تسجّل المنصة أي مساحة في المعاينة.',
  'partner3.refusal.reportFiling': 'لا يُقارن أي تقدير بمعاينة، ولا يُختم أي تقرير، ولا يُدّعى شيء حول كيفية تقديم التقرير أو موعده.',
  'partner3.refusal.evidenceBoardQueue': 'الأعداد في هذه الصفحة هي أعداد المطالبات حسب الحالة ولا شيء غير ذلك: لا تُحصى أي صورة أو فيديو أو مستند أو فحص، ولا يُوعد بأي مدة إنجاز.',
