  'partner6.language.current': 'الوحدة الآن بلغة',
  'partner6.chain.notificationForm.error.title': 'لم يُضبط شيء',
  'partner6.chain.notificationForm.error.body': 'هذه ليست لغة تقدّمها هذه الوحدة، لذا لم يُضبط شيء. عُد إلى الصفحة واختر إحدى اللغات المدرجة هناك.',
  'partner6.chain.notificationForm.review.title': 'تحقّق من اختيارك',
  'partner6.chain.notificationForm.review.body': 'هذه هي اللغة التي اخترتها، مكتوبة بنفسها. لا يُضبط شيء حتى تضغط الزر أدناه؛ وهو يغيّر هذا المتصفح فقط.',
  'partner6.chain.notificationForm.success.title': 'ضُبطت اللغة',
  'partner6.chain.notificationForm.success.body': 'تستخدم الوحدة الآن اللغة المذكورة أدناه في هذا المتصفح. النص الذي لا تتوفر له ترجمة بعد لا يزال يُعرض بالإنجليزية.',
  'partner6.chain.notificationForm.failure.title': 'لم يتغير شيء',
  'partner6.chain.notificationForm.failure.body': 'تعذّر ضبط اللغة لهذا المتصفح، لذا لم يتغير شيء. عُد إلى الصفحة واختر مرة أخرى.',
  'partner6.chain.notificationAct.confirm.title': 'لا شيء للتأكيد',
  'partner6.chain.notificationAct.confirm.body': 'هذه الصفحة لا تقرأ شيئًا، لذا لا يوجد ما يُعاد قراءته ولا ما يُؤكَّد. لا يُخزَّن لك أي تفضيل لتحمّله.',
  'partner6.chain.notificationAct.success.title': 'لم يتغير شيء',
  'partner6.chain.notificationAct.success.body': 'لم يحدث شيء، لذا لم ينجح شيء: لم يُحفظ أي تفضيل ولم يُغيَّر.',
  'partner6.chain.notificationAct.failure.title': 'لم تُجرَ أي محاولة',
  'partner6.chain.notificationAct.failure.body': 'لم تُجرَ أي محاولة ولم يتغير شيء. الصفحة التي أتيت منها لا تقرأ شيئًا، لذا لا يوجد ما يُعاد قراءته.',
  'partner6.chain.notificationsAct.confirm.title': 'لا شيء لتعليمه كمقروء',
  'partner6.chain.notificationsAct.confirm.body': 'لا توجد رسالة هنا، لذا لا يمكن تعليم أي شيء كمقروء ولا يوجد ما يُؤكَّد.',
  'partner6.chain.notificationsAct.success.title': 'لم يتغير شيء',
  'partner6.chain.notificationsAct.success.body': 'لم يحدث شيء، لذا لم ينجح شيء: لم تُعلَّم أي رسالة كمقروءة.',
  'partner6.chain.notificationsAct.failure.title': 'لم تُجرَ أي محاولة',
  'partner6.chain.notificationsAct.failure.body': 'لم تُجرَ أي محاولة ولم يتغير شيء. الصفحة التي أتيت منها لا تقرأ شيئًا، لذا لا يوجد ما يُعاد قراءته.',
  'partner6.refusal.sameEngine': 'خدمة الرسائل في المنصة للمزارعين والمنظمات لا ترسل شيئًا إلى أي فرد لدى الشريك: لا تنطبق عليك هنا أي مستويات رسائل.',
  'partner6.refusal.inboxCounters': 'لا يوجد صندوق وارد لك في هذه الوحدة، لذا لا يُحصى شيء: لا رسائل غير مقروءة ولا فاشلة ولا مجمّعة.',
  'partner6.refusal.inboxItems': 'لا تُرسل إليك هنا أي رسالة عن مطالبة أو معاينة أو دفع أو موافقة أو تذكير، ولا تذكر أي رسالة هنا أبدًا اسم شخص آخر أو مكانًا.',
  'partner6.refusal.otherChannels': 'لا تُفحص أي قائمة "عدم الإزعاج" لرقمك، ولا تحلّ أي قناة أخرى محل الرسالة النصية عند فشلها.',
  'partner6.refusal.markAllRead': 'لا يمكن تعليم أي شيء كمقروء: لا توجد رسالة هنا لقراءتها.',
  'partner6.refusal.expandGrouped': 'لا تُجمع أي رسائل في ملخص واحد لك، لذا لا يوجد ما يُوسَّع ولا يُؤجَّل شيء لوقت لاحق.',
  'partner6.refusal.pageList': 'لا يُدرج شيء هنا، لذا لا يُقسَّم شيء إلى صفحات ولا يوجد خيار لحجم الصفحة.',
  'partner6.refusal.phoneAlerts': 'لا يصل إلى هاتفك أي تنبيه من هذه الوحدة غير رمز تسجيل الدخول أو دعوة الفريق.',
  'partner6.refusal.deliveryLogHere': 'هذه الصفحة لا تحتفظ بسجل تسليم خاص بها: سجل التسليم الوحيد الذي يمكنك قراءته هو سجل خطافات الويب لمنظمتك، في صفحة خطافات الويب.',
  'partner6.refusal.notificationsNoError': 'هذه الصفحة لا تقرأ شيئًا، لذا ليس لديها خطأ تحميل ولا شيء لإعادة المحاولة.',
  'partner6.refusal.noOrgInbox': 'لا يوجد صندوق وارد هنا إطلاقًا — لا لك ولا لمنظمتك — لذا لا يمكن مشاركة شيء منه.',
  'partner6.refusal.prefsMatrix': 'لا يوجد جدول رسائل وقنوات لتفعيلها أو إيقافها: لا تُرسل إليك هنا أي رسالة أخرى.',
  'partner6.refusal.dutyLock': 'لا توجد هنا رسالة تطلب منك أن تقرر أي شيء نيابةً عن مزارع: لا يُرسل إليك شيء من هذا النوع.',
  'partner6.refusal.securityChannels': 'يُرسل رمز تسجيل الدخول عبر SMS فقط — لا عبر البريد الإلكتروني ولا داخل الوحدة.',
  'partner6.refusal.eventCount': 'لا تنطبق عليك أي قائمة بأنواع الرسائل، لذا لا يُعرض أي منها ولا يُخفى.',
  'partner6.refusal.quietWindow': 'لا توجد نافذة أوقات هادئة لضبطها: لا يُرسل إليك شيء يمكن تأجيله.',
  'partner6.refusal.dailySummary': 'لا يُعَدّ لك أي بريد إلكتروني بملخص يومي، لذا لا يوجد وقت لاختياره.',
  'partner6.refusal.savePrefs': 'لا يُحفظ هنا شيء سوى لغة الوحدة: لا يوجد تفضيل آخر للاحتفاظ به.',
  'partner6.refusal.defaultsState': 'لا تُضبط لك أي إعدادات افتراضية للرسائل، لأنه لا يُرسل إليك هنا شيء سوى رمز تسجيل الدخول أو دعوة الفريق.',
  'partner6.refusal.prefsNoError': 'لا يُقرأ شيء لرسم هذه الصفحة، لذا ليس لديها خطأ تحميل ولا شيء لإعادة المحاولة؛ ولا يُخزَّن لك أي تفضيل آخر.',
  'partner6.refusal.colleagueReach': 'لا يستطيع أحد في منظمتك رؤية ما إذا كان يمكن الوصول إلى زميل: لا يوجد مثل هذا العرض، وصفحة الفريق تعرض الأسماء والأدوار فقط.',
  'partner6.refusal.templateParity': 'ليست كل سطور نصوص الوحدة متوفرة بالهندية والغوجاراتية بعد: النص القديم الذي لا ترجمة له يُعرض بالإنجليزية.',
  'partner6.refusal.languageReviewChecker': 'لا يفحص أي شخص ثانٍ اختيار اللغة: إنه لك وحدك ولا يغيّر إلا هذا المتصفح.',
  'partner6.refusal.languageNoAudit': 'لا يُكتب أي قيد في السجل لاختيار اللغة: إنه إعداد لهذا المتصفح، لا سجل عن أي أحد.',
  'lang.draft': 'مسودة آلية',
